import {wikiUrl} from './core.js';
const node=(id,title,category,summary,question,links,extra={})=>({id,title,category,summary,question,links,source:{label:'Read on Wikipedia',url:wikiUrl(title)},kind:'curated',...extra});
export const NODES = [
node('music','Music','Mind & sound','A pattern in the air can become a feeling, a memory or a way of belonging. Music is a meeting point for rhythm, perception and culture. The interesting question is not just how sound works, but how we make meaning from it.','Why can the same song mean something different to two people?',['rhythm','memory','emotion','acoustics','silence','synesthesia'],{eyebrow:'A pattern becomes a feeling',fact:'Start with sound. Follow it into memory.',read:'3 min'}),
node('rhythm','Rhythm','Mind & sound','Rhythm organises events in time. We hear it in music, feel it in movement and notice it in repeated patterns. A beat gives us something to anticipate; a pause can make that expectation visible.','When does repetition become a rhythm?',['music','time','dance','pattern']),
node('memory','Autobiographical memory','Mind & sound','Autobiographical memory connects experiences to our sense of self. A cue such as a song or a smell can bring an earlier moment into focus. Remembering is an act of reconstruction rather than a perfect recording.','Are you remembering the event, or the last time you remembered it?',['music','nostalgia','smell','time','emotion']),
node('emotion','Emotion','Mind & sound','Emotions involve experience, behaviour and bodily changes. Their definitions and boundaries are debated. Following emotion into music or art opens questions about how interpretation, context and expectation shape a response.','How much of a feeling comes from the situation around it?',['music','memory','color','awe']),
node('acoustics','Acoustics','Mind & sound','Acoustics is the study of sound. Vibrations travel through a medium, interact with spaces and reach a listener. The same instrument can sound different in a small room, a cathedral or the open air.','Can a room become part of an instrument?',['music','architecture','silence','rhythm']),
node('silence','Silence','Art & culture','Silence may mean an absence of sound, a pause in speech or a deliberate artistic choice. In music and conversation, what is withheld can change how we hear what comes next.','What do you notice when the expected sound disappears?',['music','acoustics','minimalism','time']),
node('synesthesia','Synesthesia','Mind & sound','Synesthesia describes experiences in which a stimulus is associated with an additional sensory or cognitive experience, such as letters having colours. It offers an unusual window into perception, but is not the same as an artistic metaphor.','Where do the boundaries between senses come from?',['color','music','perception']),
node('nostalgia','Nostalgia','Mind & sound','Nostalgia is a longing for the past, often coloured by affection. Music, objects and places can become cues. It is worth separating the history of a moment from the feeling we attach to it.','Can you be nostalgic for a time you never lived through?',['memory','music','cities','photography']),
node('smell','Olfaction','Living world','Olfaction is the sense of smell. It turns airborne chemical signals into perception, and connects with questions about memory, food and place. A familiar smell can give an ordinary setting a personal history.','What would a map of your city look like if it were made of smells?',['memory','cities','perception']),
node('time','Time perception','Mind & sound','Clock time and experienced time are different subjects. Time perception concerns how we judge duration and sequence. Attention, context and memory can all enter the picture, so an interval can feel different while it happens and when we look back.','Why does a day feel different in the moment and in memory?',['memory','rhythm','circadian','relativity','silence'],{eyebrow:'An hour is not always an hour'}),
node('dance','Dance','Art & culture','Dance brings movement, rhythm and expression together. It can be a performance, a ritual, a social activity or a personal practice. Follow the movement and you soon reach questions about culture and coordination.','How do people find a shared rhythm without speaking?',['rhythm','music','pattern','cities']),
node('pattern','Pattern','Living world','A pattern is a regularity we can recognise in the world or in an idea. Patterns connect mathematics, design and nature. Recognising one is useful, but it does not by itself explain what produced it.','When are we discovering a pattern, and when are we imposing one?',['fractal','symmetry','rhythm','perception']),
node('fractal','Fractal','Living world','Fractals are mathematical objects with intricate structure across scales. Some natural forms resemble fractal patterns over limited ranges. A branching tree, for example, invites a mathematical comparison without being a perfect mathematical fractal.','How much of a whole can you recognise in one small part?',['pattern','trees','symmetry','coastline'],{eyebrow:'A world inside a world'}),
node('trees','Tree','Living world','Trees are long-lived plants whose forms reflect growth and environment. Their branching structures invite comparisons with rivers and other networks. Those visual similarities are a starting point for investigation, not evidence of identical mechanisms.','Why do so many different things branch?',['fractal','pattern','cities','circadian']),
node('symmetry','Symmetry','Living world','Symmetry describes what stays unchanged under a transformation, such as reflection or rotation. It appears in mathematics, natural forms and art. A deliberate break in symmetry can become the most noticeable part of a composition.','Why does an almost-symmetrical thing catch the eye?',['pattern','fractal','architecture','color']),
node('coastline','Coastline paradox','Living world','The measured length of a coastline depends on the scale used to measure it. Smaller measuring units can follow more of its irregular detail. This is an approachable way into the surprising relationship between measurement and scale.','Can a measurement be precise without being independent of your method?',['fractal','pattern','maps']),
node('cities','Urban design','Places & people','Urban design considers how buildings, streets and public spaces fit together. A city can be read as a network of routes, encounters and boundaries. The design of a place helps frame what people can do there.','What makes a place invite you to stay?',['architecture','thirdplace','psychogeography','maps','trees'],{eyebrow:'The city between the buildings'}),
node('architecture','Architecture','Places & people','Architecture shapes spaces for human use. It brings practical constraints together with aesthetics and cultural meaning. Light, sound, materials and movement all help determine how a building is experienced.','What changes when you listen to a building instead of looking at it?',['cities','acoustics','symmetry','minimalism']),
node('thirdplace','Third place','Places & people','A third place is a social setting outside home and work, a concept associated with sociologist Ray Oldenburg. Cafés, libraries and other gathering places offer ways to think about everyday community.','Where can you spend time without needing a specific reason to be there?',['cities','dance','psychogeography']),
node('psychogeography','Psychogeography','Places & people','Psychogeography explores how environments relate to feelings and behaviour. Its history includes playful, critical ways of moving through cities. A wandering route can reveal things that a commute leaves unnoticed.','What would you discover if you took the least efficient route home?',['cities','maps','nostalgia','photography']),
node('maps','Cartography','Places & people','Cartography is the making and study of maps. Every map selects, simplifies and arranges information. That makes maps useful, while also making their purpose and omissions worth examining.','What does a map ask you not to notice?',['cities','coastline','moon','psychogeography']),
node('moon','Moon','Space & wonder','The Moon is Earth’s natural satellite. Its phases, surface and orbital motion have inspired observation, exploration and storytelling. One familiar object can lead into astronomy, geography and cultural history.','How can something so familiar still contain so many unknowns?',['awe','relativity','maps','circadian'],{eyebrow:'A familiar stranger in the sky',source:{label:'NASA · Moon overview',url:'https://science.nasa.gov/moon/'}}),
node('awe','Awe','Space & wonder','Awe is often discussed as a response to something vast or difficult to fit into an existing understanding. A night sky, a work of art or an unfamiliar idea can all prompt that kind of encounter.','Does wonder begin where your explanation runs out?',['moon','emotion','fractal','photography']),
node('relativity','Theory of relativity','Space & wonder','Einstein’s theories of relativity connect space, time and gravity. They describe physical relationships, distinct from the psychology of how time feels. Putting those subjects next to each other makes the difference itself interesting.','What is the difference between time changing physically and time feeling different?',['moon','time','maps']),
node('circadian','Circadian rhythm','Living world','Circadian rhythms are biological cycles with a roughly 24-hour period. They connect organisms with environmental cues such as light. They offer a bridge between the time on a clock and the rhythms of living systems.','What does it mean for a body to keep time?',['time','trees','rhythm','moon']),
node('color','Color','Art & culture','Colour emerges from interactions between light, objects and visual perception. It is also a language of culture and design. Changing the surrounding colours can change how a patch appears.','How much of a colour belongs to its surroundings?',['perception','synesthesia','minimalism','photography'],{eyebrow:'More than meets the eye'}),
node('perception','Perception','Mind & sound','Perception is how sensory information becomes an organised experience of the world. Attention, context and prior experience matter. An illusion can be useful because it exposes assumptions that normally go unnoticed.','What does an illusion reveal about ordinary seeing?',['color','synesthesia','pattern','smell']),
node('minimalism','Minimalism','Art & culture','Minimalism is associated with reduction and restraint across several creative fields. Different movements use the term differently. Removing elements can place more attention on material, space, repetition or a small change.','How little can you leave and still say something?',['silence','architecture','color','pattern']),
node('photography','Photography','Art & culture','Photography uses light to make images, but a photograph is also a selection: a frame, a moment and a point of view. It can document a place while changing how that place is remembered.','Is a photograph a record of what happened, or of what someone noticed?',['memory','nostalgia','color','psychogeography','awe'])
];
